int main(int argc,char** argv){try{std::string adapter;if(argc==3&&std::string(argv[1])=="--adapter")adapter=argv[2];else if(argc!=1)throw std::runtime_error("Usage: native_smoke_service_tests [--adapter substring]");const auto bytes=readFile("build/smoke-service/fixture.cooked.json");const auto asset=e::parseCooked(bytes);Rig rig(adapter);require(rig.debug,"D3D12 debug layer required");std::cerr<<"assetContract\n";assetContract(rig,asset,bytes);std::cerr<<"lifecycle\n";lifecycle(rig,asset);std::cerr<<"tails\n";tails(rig,asset);std::cerr<<"admissionRollback\n";admissionRollback(rig,asset);std::cerr<<"queuedVisualSkip\n";queuedVisualSkip(rig,asset);std::cerr<<"dispatchFairness\n";dispatchFairness(rig,asset);std::cerr<<"failedDriver\n";failedDriver(rig,asset);const auto errors=rig.debugErrors();require(errors==0,"Smoke service D3D12 debug errors");std::cout<<Json{{"schema","nativegpu.smoke-service-evidence/1"},{"ok",true},{"groups",groups},{"checks",checks},{"comparisons",comparisons},{"adapter",rig.adapter},{"debugLayer",rig.debug},{"debugErrors",errors},{"cases",cases},{"rendererIntegrated",false},{"worldFieldIntegrated",false}}.dump()<<'\n';}catch(const std::exception& e){std::cerr<<"Smoke service failed after "<<checks<<" checks: "<<e.what()<<'\n';return 1;}}
